import React, { useState } from 'react';
import axios from 'axios';

const AppointmentForm = () => {
  const [formData, setFormData] = useState({ name: "", phone: "", date: "", message: "" });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      // The endpoint should match your server's endpoint
      const res = await axios.post("http://localhost:5000/api/appointments", formData);
      if (res.data.success) {
        alert("Appointment submitted successfully!");
        setFormData({ name: "", phone: "", date: "", message: "" });
      }
    } catch (err) {
      console.error(err);
      alert("Failed to submit appointment.");
    }
  };

  return (
    <section className="bg-white py-16 px-4">
      <div className="max-w-2xl mx-auto p-8 bg-gray-50 rounded-lg shadow-md">
        <h2 className="text-3xl font-bold text-center mb-6 text-gray-800">Book an Appointment</h2>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-1">Your Name</label>
            <input type="text" id="name" name="name" placeholder="Enter your full name" value={formData.name} onChange={handleChange} required 
                   className="w-full px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-brand-green focus:border-brand-green" />
          </div>
          <div>
            <label htmlFor="phone" className="block text-sm font-medium text-gray-700 mb-1">Phone Number</label>
            <input type="tel" id="phone" name="phone" placeholder="Enter your phone number" value={formData.phone} onChange={handleChange} required 
                   className="w-full px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-brand-green focus:border-brand-green" />
          </div>
          <div>
            <label htmlFor="date" className="block text-sm font-medium text-gray-700 mb-1">Preferred Date</label>
            <input type="date" id="date" name="date" value={formData.date} onChange={handleChange} required 
                   className="w-full px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-brand-green focus:border-brand-green" />
          </div>
          <div>
            <label htmlFor="message" className="block text-sm font-medium text-gray-700 mb-1">Reason for Appointment</label>
            <textarea id="message" name="message" placeholder="Briefly describe the reason for your visit" value={formData.message} onChange={handleChange} required rows="4"
                      className="w-full px-4 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-brand-green focus:border-brand-green"></textarea>
          </div>
          <button type="submit" 
                  className="w-full bg-brand-green text-white font-bold py-3 px-6 rounded-md hover:bg-brand-green-dark transition-all duration-300">
            Submit Appointment
          </button>
        </form>
      </div>
    </section>
  );
};

export default AppointmentForm;
